<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides development plan behavior within the WorkIntel application. */ class DevelopmentPlan extends Model{protected $fillable=['uuid','workspace_id','member_id','manager_member_id','title','objective','status','start_date','target_date','summary'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['start_date'=>DateOnly::class,'target_date'=>DateOnly::class];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Handles the items operation for the current WorkIntel workflow. */ public function items():HasMany{return $this->hasMany(DevelopmentPlanItem::class);}}
